import os

def get_abs_path(path):
    """Get absolute path of a file/directory/symlink"""
    return os.path.abspath(path)

def is_symlink(path):
    """Check if path is a symlink"""
    return os.path.islink(path)

def is_regular_file(path):
    """Check if path is a regular file (not symlink, not directory)"""
    return os.path.isfile(path) and not os.path.islink(path)

def is_directory(path):
    """Check if path is a directory"""
    return os.path.isdir(path)

# Start at /workdir/start
start_path = "/workdir/start"
chain = []
current = start_path

# First, get absolute path of start
current_abs = os.path.abspath(current)
chain.append(current_abs)

while True:
    # Check if current is a regular file
    if is_regular_file(current_abs):
        break
    # Check if it's a symlink
    if is_symlink(current_abs):
        # Read the symlink target
        target = os.readlink(current_abs)
        # Resolve to absolute path
        if os.path.isabs(target):
            next_path = os.path.abspath(target)
        else:
            next_path = os.path.abspath(os.path.join(os.path.dirname(current_abs), target))
        current = next_path  # Update current to the target location
        chain.append(current)  # Add the target to chain
    elif is_directory(current_abs):
        # It's a directory - need to find the "main chain" link inside it
        # According to puzzle design, likely "next" symlink
        # Let's find symlinks in this directory
        try:
            entries = os.listdir(current_abs)
            # Look for a symlink named "next"
            next_link_path = None
            for entry in entries:
                entry_path = os.path.join(current_abs, entry)
                if os.path.islink(entry_path):
                    if entry == "next":
                        next_link_path = entry_path
                    # If no "next", maybe take first symlink?
                    # For now, let's prioritize "next"
            if next_link_path:
                target = os.readlink(next_link_path)
                if os.path.isabs(target):
                    next_path = os.path.abspath(target)
                else:
                    next_path = os.path.abspath(os.path.join(os.path.dirname(next_link_path), target))
                current = next_path
                chain.append(current)
            else:
                # Fallback: take first symlink found
                # Actually, let me implement it properly - find first symlink
                first_symlink_path = None
                for entry in os.listdir(current_abs):
                    entry_path = os.path.join(current_abs, entry)
                    if os.path.islink(entry_path):
                        first_symlink_path = entry_path
                        break
                if first_symlink_path:
                    target = os.readlink(first_symlink_path)
                    if os.path.isabs(target):
                        next_path = os.path.abspath(target)
                    else:
                        next_path = os.path.abspath(os.path.join(os.path.dirname(first_symlink_path), target))
                    current = next_path
                    chain.append(current)
        except PermissionError:
            pass
    else:
        # It's a regular file or other - if it's a regular file we would have stopped earlier
        # But if it's not a symlink and not a directory but not regular file? 
        # Should not happen based on problem description
        break

# Output results
with open("/workdir/sol.txt", "w") as f:
    f.write(chain[-1] + "\n")  # The absolute path where we stop
with open("/workdir/sol_chain.txt", "w") as f:
    for path in chain:
        f.write(path + "\n")

print("Chain:", chain)
